:root {
  --bg: #070d17;
  --bg-alt: #0d1727;
  --panel: rgba(14, 22, 34, 0.82);
  --panel-strong: rgba(20, 31, 49, 0.95);
  --line: rgba(135, 163, 196, 0.18);
  --line-strong: rgba(149, 171, 205, 0.26);
  --text: #ecf4ff;
  --muted: #8aa1bc;
  --accent: #7ef6c5;
  --accent-2: #64c5ff;
  --warning: #f7c86d;
  --danger: #ff7d8d;
  --shadow: rgba(11, 18, 28, 0.5);
  --radius: 18px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background:
    radial-gradient(circle at top, rgba(94, 126, 204, 0.15), transparent 30%),
    linear-gradient(180deg, #071019 0%, #070d17 35%, #050a12 100%);
  color: var(--text);
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

body {
  min-height: 100vh;
}

button {
  font: inherit;
}

.app-shell {
  display: grid;
  grid-template-columns: minmax(0, 2.05fr) minmax(280px, 0.7fr);
  gap: 20px;
  max-width: 1380px;
  margin: 0 auto;
  padding: 22px 20px 40px;
}

.topbar {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 6px 16px;
  border-bottom: 1px solid var(--line);
}

.brand-wrap {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  display: flex;
  gap: 5px;
  align-items: end;
  height: 30px;
  transform: skewY(-18deg);
}

.brand-mark span {
  display: block;
  width: 7px;
  border-radius: 5px;
  background: linear-gradient(180deg, var(--accent), #c7ffe5);
  box-shadow: 0 0 12px rgba(126, 246, 197, 0.5);
}

.brand-mark span:nth-child(1) { height: 12px; }
.brand-mark span:nth-child(2) { height: 24px; }
.brand-mark span:nth-child(3) { height: 16px; opacity: 0.8; }

.brand-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-text strong {
  font-size: clamp(1.2rem, 2vw, 1.9rem);
  letter-spacing: 0.22em;
}

.brand-text small {
  color: var(--muted);
  font-size: 0.62rem;
  letter-spacing: 0.18em;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.route-pill,
.ghost-button,
.primary-button,
.secondary-button,
.network-item,
.bot-card,
.upgrade-card {
  border: 1px solid var(--line);
  border-radius: 12px;
}

.ghost-button,
.primary-button,
.secondary-button {
  padding: 10px 14px;
  cursor: pointer;
  transition: 0.2s ease;
}

.ghost-button {
  background: rgba(255, 255, 255, 0.02);
  color: var(--text);
}

.primary-button {
  background: linear-gradient(135deg, var(--accent), #91f7d7);
  color: #071019;
  font-weight: 700;
  border-color: transparent;
  box-shadow: 0 12px 28px rgba(126, 246, 197, 0.2);
}

.secondary-button {
  background: rgba(100, 197, 255, 0.08);
  color: var(--text);
}

.ghost-button:hover,
.primary-button:hover,
.secondary-button:hover,
.network-item:hover,
.bot-card:hover,
.upgrade-card:hover {
  transform: translateY(-1px);
}

.route-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.route-pill .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 12px rgba(126, 246, 197, 0.8);
}

.route-off {
  color: var(--muted);
  border-color: rgba(138, 161, 188, 0.15);
}

.route-off .dot {
  background: var(--muted);
  box-shadow: none;
}

.game-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.4fr);
  gap: 20px;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.panel {
  background: linear-gradient(180deg, rgba(18, 28, 40, 0.94), rgba(12, 20, 31, 0.94));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 18px 40px var(--shadow);
  padding: 20px;
}

.networks-panel,
.fleet-panel,
.upgrades-panel {
  min-height: 220px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.eyebrow {
  color: var(--muted);
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.panel-header h2 {
  margin: 0;
  font-size: clamp(1.2rem, 2vw, 1.65rem);
}

.mini-stat {
  color: var(--accent);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: rgba(126, 246, 197, 0.06);
  border: 1px solid rgba(126, 246, 197, 0.2);
  border-radius: 999px;
  padding: 7px 10px;
}

.network-list,
.bot-list,
.upgrade-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.network-item {
  background: rgba(255, 255, 255, 0.02);
  padding: 14px 14px 12px;
  cursor: pointer;
  transition: 0.2s ease;
}

.network-item.active {
  border-color: rgba(126, 246, 197, 0.7);
  background: linear-gradient(180deg, rgba(126, 246, 197, 0.08), rgba(37, 71, 79, 0.18));
  box-shadow: inset 0 0 0 1px rgba(126, 246, 197, 0.08);
}

.network-item.disabled {
  opacity: 0.53;
}

.network-topline,
.network-meta,
.bot-head,
.upgrade-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.network-name {
  font-size: 1.06rem;
  font-weight: 700;
}

.network-badge {
  border-radius: 999px;
  background: rgba(100, 197, 255, 0.08);
  border: 1px solid rgba(100, 197, 255, 0.2);
  color: var(--accent-2);
  font-size: 0.64rem;
  letter-spacing: 0.12em;
  padding: 5px 8px;
  text-transform: uppercase;
}

.network-meta {
  margin-top: 10px;
  color: var(--muted);
  font-size: 0.78rem;
}

.active-network-card {
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, rgba(126, 246, 197, 0.05), rgba(10, 19, 27, 0.8));
  border-radius: 18px;
  padding: 18px 18px 16px;
}

.network-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.signal {
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.reward {
  margin-top: 8px;
  font-size: clamp(1.5rem, 2vw, 2.3rem);
  font-weight: 700;
}

.network-index {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 1px solid rgba(126, 246, 197, 0.48);
  font-weight: 700;
  color: var(--accent);
  background: rgba(126, 246, 197, 0.08);
}

.network-description {
  color: var(--muted);
  line-height: 1.6;
  margin: 0 0 18px;
  min-height: 72px;
}

.metrics-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 18px;
}

.metrics-row div {
  padding: 10px 10px 8px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(255, 255, 255, 0.02);
}

.metrics-row span {
  display: block;
  color: var(--muted);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 6px;
}

.metrics-row strong {
  font-size: 1.02rem;
}

.action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.bot-card,
.upgrade-card {
  background: rgba(255, 255, 255, 0.02);
  padding: 12px 12px 10px;
}

.bot-card.is-paused {
  border-color: rgba(247, 200, 109, 0.5);
}

.bot-head strong,
.upgrade-head strong {
  display: block;
  font-size: 1.02rem;
}

.bot-status,
.upgrade-level,
.bot-power {
  color: var(--muted);
  font-size: 0.72rem;
}

.bot-card .bot-meta,
.upgrade-card .upgrade-meta,
.stat-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
}

.bot-card button,
.upgrade-card button {
  margin-top: 10px;
  width: 100%;
}

.stat-panel,
.system-panel {
  padding-top: 16px;
}

.stat-stack,
.system-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat-item {
  padding: 12px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.03);
  background: rgba(255, 255, 255, 0.02);
}

.stat-item span {
  color: var(--muted);
}

.stat-item strong {
  font-size: 1.08rem;
}

.system-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.system-list li {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 10px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.02);
}

.system-list span {
  color: var(--muted);
}

.toast {
  position: fixed;
  right: 20px;
  bottom: 24px;
  background: rgba(10, 16, 23, 0.92);
  border: 1px solid rgba(126, 246, 197, 0.25);
  color: var(--text);
  border-radius: 12px;
  padding: 12px 16px;
  box-shadow: 0 18px 35px rgba(0, 0, 0, 0.2);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: 0.2s ease;
}

.toast.visible {
  opacity: 1;
  transform: translateY(0);
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .game-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    order: 2;
  }
}

@media (max-width: 560px) {
  .app-shell {
    padding: 16px 12px 28px;
  }

  .topbar {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .topbar-actions {
    width: 100%;
    justify-content: space-between;
  }

  .metrics-row {
    grid-template-columns: 1fr;
  }

  .action-row {
    flex-direction: column;
  }

  .action-row button {
    width: 100%;
  }
}

(() => {
  'use strict';

  const STORAGE_KEY = 'miner-aurora-save-v1';
  const MAX_NETWORKS = 6;
  const DEFAULT_STATE = {
    credits: 0,
    wallet: 0,
    totalEarned: 0,
    unlockedNetworks: 1,
    activeNetworkId: 0,
    routeMode: true,
    bots: [
      { id: 1, name: 'A-01', level: 1, power: 1.2, paused: false },
      { id: 2, name: 'C-04', level: 1, power: 1.2, paused: false },
    ],
    upgrades: {
      nodeArray: 0,
      relaySync: 0,
      crystalCache: 0,
    },
    lastTick: Date.now(),
  };

  const NETWORKS = [
    {
      id: 0,
      name: 'Asterion',
      reward: 8,
      risk: 'Basso',
      power: 8,
      unlockCost: 0,
      description: 'Fino al 91% di sfide gestibili in modo sicuro, con canali di routing leggeri e costi bassi.',
      signal: 'Segnale stabile',
    },
    {
      id: 1,
      name: 'Valkyr',
      reward: 14,
      risk: 'Medio',
      power: 14,
      unlockCost: 38,
      description: 'Reti ad alta concentrazione con traffico intenso, ma con margini di profitto più profondi.',
      signal: 'Rondò intenso',
    },
    {
      id: 2,
      name: 'Nyx',
      reward: 22,
      risk: 'Medio',
      power: 22,
      unlockCost: 96,
      description: 'Superfici caotiche e distribuite, adatte a bot con sensori avanzati e cache veloci.',
      signal: 'Massa neutronica',
    },
    {
      id: 3,
      name: 'Khepri',
      reward: 34,
      risk: 'Alto',
      power: 34,
      unlockCost: 220,
      description: 'Cicli di scansione profondi, adatti a team con sincronizzazione e coesione robuste.',
      signal: 'Sottoreticolo instabile',
    },
    {
      id: 4,
      name: 'Rhea',
      reward: 52,
      risk: 'Alto',
      power: 52,
      unlockCost: 520,
      description: 'Domini ad alta latenza con modelli di valore frammentati e rischi da monitorare costantemente.',
      signal: 'Campo di disturbo',
    },
    {
      id: 5,
      name: 'Helios',
      reward: 80,
      risk: 'Estremo',
      power: 80,
      unlockCost: 1300,
      description: 'Rete di frontiera: guadagni massimi, ma solo per flotte ben coordinate e ben supportate.',
      signal: 'Trasmissione critica',
    },
  ];

  const UPGRADE_DEFS = [
    {
      id: 'nodeArray',
      name: 'Node Array',
      description: 'Raddoppia la potenza base delle reti attive.',
      baseCost: 20,
      scaling: 1.6,
      effect: (level) => ({ botMult: 1 + level * 0.15, networkMult: 1 + level * 0.12 }),
    },
    {
      id: 'relaySync',
      name: 'Relay Sync',
      description: 'Aumenta la velocità di scansione del 25% per livello.',
      baseCost: 35,
      scaling: 1.8,
      effect: (level) => ({ scanMult: 1 + level * 0.25 }),
    },
    {
      id: 'crystalCache',
      name: 'Crystal Cache',
      description: 'Riduce il costo delle nuove assunzioni e ottimizza il routing wallet.',
      baseCost: 60,
      scaling: 1.9,
      effect: (level) => ({ hireDiscount: 1 - Math.min(level * 0.08, 0.32), routeBoost: 1 + level * 0.1 }),
    },
  ];

  const els = {
    networkList: document.getElementById('networkList'),
    networkProgress: document.getElementById('networkProgress'),
    activeNetworkName: document.getElementById('activeNetworkName'),
    scanBtn: document.getElementById('scanBtn'),
    networkSignal: document.getElementById('networkSignal'),
    networkReward: document.getElementById('networkReward'),
    networkIndex: document.getElementById('networkIndex'),
    networkDescription: document.getElementById('networkDescription'),
    networkRisk: document.getElementById('networkRisk'),
    networkPower: document.getElementById('networkPower'),
    networkUnlock: document.getElementById('networkUnlock'),
    hireBtn: document.getElementById('hireBtn'),
    routeBtn: document.getElementById('routeBtn'),
    routeStatus: document.getElementById('routeStatus'),
    resetBtn: document.getElementById('resetBtn'),
    botList: document.getElementById('botList'),
    upgradeList: document.getElementById('upgradeList'),
    creditsStat: document.getElementById('creditsStat'),
    walletStat: document.getElementById('walletStat'),
    totalStat: document.getElementById('totalStat'),
    onlineBots: document.getElementById('onlineBots'),
    unlockedCount: document.getElementById('unlockedCount'),
    prodRate: document.getElementById('prodRate'),
    statusBadge: document.getElementById('statusBadge'),
    toast: document.getElementById('toast'),
  };

  let state = loadState();
  let toastTimer = null;

  function loadState() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return structuredClone(DEFAULT_STATE);

    try {
      const saved = JSON.parse(raw);
      return {
        ...structuredClone(DEFAULT_STATE),
        ...saved,
        bots: Array.isArray(saved.bots) ? saved.bots : structuredClone(DEFAULT_STATE.bots),
        upgrades: { ...structuredClone(DEFAULT_STATE.upgrades), ...(saved.upgrades || {}) },
      };
    } catch {
      return structuredClone(DEFAULT_STATE);
    }
  }

  function saveState() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function formatCredits(value) {
    return `${Number(value).toLocaleString('it-IT', { maximumFractionDigits: 1 })} cr`;
  }

  function showToast(text) {
    els.toast.textContent = text;
    els.toast.classList.add('visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      els.toast.classList.remove('visible');
    }, 1600);
  }

  function getActiveNetwork() {
    return NETWORKS[state.activeNetworkId] || NETWORKS[0];
  }

  function getUpgradeCost(kind) {
    const def = UPGRADE_DEFS.find((upgrade) => upgrade.id === kind);
    const currentLevel = state.upgrades[kind] || 0;
    return Math.round(def.baseCost * Math.pow(def.scaling, currentLevel));
  }

  function getBotHireCost() {
    const active = getActiveNetwork();
    const discount = state.upgrades.crystalCache ? 1 - Math.min((state.upgrades.crystalCache || 0) * 0.08, 0.32) : 1;
    return Math.round(active.unlockCost * 0.7 * discount + state.bots.length * 12);
  }

  function getNetworkPowerMultiplier() {
    const upgrade = state.upgrades.nodeArray || 0;
    return 1 + upgrade * 0.22;
  }

  function getNetworkProduction() {
    const active = getActiveNetwork();
    const botTotal = state.bots.reduce((sum, bot) => {
      if (bot.paused) return sum;
      const base = bot.power * (1 + (state.upgrades.nodeArray || 0) * 0.15);
      return sum + base;
    }, 0);

    const relayBonus = 1 + (state.upgrades.relaySync || 0) * 0.25;
    const routeBonus = state.routeMode ? 1 + (state.upgrades.crystalCache || 0) * 0.1 : 1;
    const total = (botTotal * relayBonus * routeBonus) * getNetworkPowerMultiplier();
    const adjusted = total * (active.reward / active.power);
    return adjusted;
  }

  function lockNetwork(id) {
    if (state.unlockedNetworks >= MAX_NETWORKS) return;
    const nextUnlocked = Math.min(MAX_NETWORKS, state.unlockedNetworks + 1);
    state.unlockedNetworks = nextUnlocked;
    state.activeNetworkId = id;
    saveState();
    render();
  }

  function setActiveNetwork(id) {
    if (id >= state.unlockedNetworks) {
      const network = NETWORKS[id];
      showToast(`Sblocca ${network.name} per ${formatCredits(network.unlockCost)}.`);
      return;
    }
    state.activeNetworkId = id;
    saveState();
    render();
  }

  function addBot() {
    const cost = getBotHireCost();
    if (state.credits < cost) {
      showToast('Crediti insufficienti per assumere un bot.');
      return;
    }
    state.credits -= cost;
    const networkBoost = 1 + (state.upgrades.nodeArray || 0) * 0.18;
    const newBot = {
      id: Date.now() + Math.random(),
      name: `B-${String(state.bots.length + 1).padStart(2, '0')}`,
      level: 1,
      power: Number((getActiveNetwork().power * 0.22 * networkBoost).toFixed(1)),
      paused: false,
    };
    state.bots.push(newBot);
    saveState();
    render();
  }

  function toggleBot(id) {
    const bot = state.bots.find((entry) => entry.id === id);
    if (!bot) return;
    bot.paused = !bot.paused;
    saveState();
    render();
  }

  function upgrade(kind) {
    const def = UPGRADE_DEFS.find((upgrade) => upgrade.id === kind);
    const cost = getUpgradeCost(kind);
    if (state.credits < cost) {
      showToast(`Mancano ${formatCredits(cost - state.credits)} per ${def.name}.`);
      return;
    }
    state.credits -= cost;
    state.upgrades[kind] = (state.upgrades[kind] || 0) + 1;
    saveState();
    render();
  }

  function scanNetwork() {
    const active = getActiveNetwork();
    if (state.credits < active.unlockCost) {
      showToast(`Richiesto ${formatCredits(active.unlockCost)} per scansionare ${active.name}.`);
      return;
    }
    const nextIndex = state.activeNetworkId + 1;
    if (nextIndex < NETWORKS.length && state.unlockedNetworks < MAX_NETWORKS) {
      const next = NETWORKS[nextIndex];
      if (state.credits >= next.unlockCost) {
        state.credits -= active.unlockCost;
        state.unlockedNetworks = Math.min(MAX_NETWORKS, state.unlockedNetworks + 1);
        state.activeNetworkId = nextIndex;
        showToast(`${next.name} sbloccata.`);
        saveState();
        render();
        return;
      }
    }

    const unlockTarget = state.unlockedNetworks;
    if (unlockTarget < NETWORKS.length && state.unlockedNetworks < MAX_NETWORKS) {
      const target = NETWORKS[unlockTarget];
      if (state.credits >= target.unlockCost) {
        state.credits -= target.unlockCost;
        state.unlockedNetworks = Math.min(MAX_NETWORKS, state.unlockedNetworks + 1);
        showToast(`${target.name} sbloccata.`);
        saveState();
        render();
        return;
      }
    }

    showToast(`Rete già allineata: ${active.name} è attiva.`);
  }

  function renderNetworks() {
    els.networkList.innerHTML = '';
    NETWORKS.forEach((network, index) => {
      const card = document.createElement('button');
      card.type = 'button';
      card.className = `network-item ${index === state.activeNetworkId ? 'active' : ''} ${index >= state.unlockedNetworks ? 'disabled' : ''}`;
      card.innerHTML = `
        <div class="network-topline">
          <span class="network-name">${network.name}</span>
          <span class="network-badge">${index === 0 ? 'Base' : 'Unlock'}</span>
        </div>
        <div class="network-meta">
          <span>${network.reward} cr/s</span>
          <span>${network.risk}</span>
        </div>
      `;
      card.addEventListener('click', () => setActiveNetwork(index));
      els.networkList.appendChild(card);
    });

    els.networkProgress.textContent = `${Math.max(1, state.unlockedNetworks)}/${MAX_NETWORKS} reti`;
  }

  function renderActiveNetwork() {
    const active = getActiveNetwork();
    const unlocked = state.unlockedNetworks;
    const unlockable = active.unlockCost > 0 && active.id >= unlocked;

    els.activeNetworkName.textContent = active.name;
    els.networkSignal.textContent = active.signal;
    els.networkReward.textContent = `+${(getNetworkProduction() / 1.3).toFixed(1)} cr/sec`;
    els.networkIndex.textContent = String(active.id + 1).padStart(2, '0');
    els.networkDescription.textContent = active.description;
    els.networkRisk.textContent = active.risk;
    els.networkPower.textContent = active.power.toString();
    els.networkUnlock.textContent = `${active.unlockCost} cr`;

    const canUnlock = active.id < NETWORKS.length - 1 && active.id >= state.unlockedNetworks - 1;
    els.scanBtn.disabled = !canUnlock || unlockable;
    els.scanBtn.textContent = unlockable ? 'Richiedi sblocco' : 'Scansiona rete';

    if (active.unlockCost > 0 && active.id >= state.unlockedNetworks) {
      els.networkUnlock.textContent = `Sbloccabile: ${active.unlockCost} cr`;
    }
  }

  function renderBots() {
    els.botList.innerHTML = '';
    if (!state.bots.length) {
      els.botList.innerHTML = '<div class="bot-card"><div class="bot-head"><strong>Nessun bot</strong></div><div class="bot-status">Assumi il primo drone.</div></div>';
      return;
    }

    state.bots.forEach((bot) => {
      const card = document.createElement('div');
      card.className = `bot-card ${bot.paused ? 'is-paused' : ''}`;
      card.innerHTML = `
        <div class="bot-head">
          <strong>${bot.name}</strong>
          <span class="bot-status">${bot.paused ? 'In pausa' : 'Online'}</span>
        </div>
        <div class="bot-meta">
          <span class="bot-power">Potenza ${bot.power.toFixed(1)}</span>
          <span class="bot-status">Lv ${bot.level}</span>
        </div>
      `;
      const toggleBtn = document.createElement('button');
      toggleBtn.type = 'button';
      toggleBtn.className = 'secondary-button';
      toggleBtn.textContent = bot.paused ? 'Riattiva' : 'Metti in pausa';
      toggleBtn.addEventListener('click', () => toggleBot(bot.id));
      card.appendChild(toggleBtn);
      els.botList.appendChild(card);
    });
  }

  function renderUpgrades() {
    els.upgradeList.innerHTML = '';
    UPGRADE_DEFS.forEach((upgrade) => {
      const level = state.upgrades[upgrade.id] || 0;
      const cost = getUpgradeCost(upgrade.id);
      const card = document.createElement('div');
      card.className = 'upgrade-card';
      card.innerHTML = `
        <div class="upgrade-head">
          <strong>${upgrade.name}</strong>
          <span class="upgrade-level">Lv ${level}</span>
        </div>
        <div class="upgrade-meta">
          <span>${upgrade.description}</span>
        </div>
      `;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'primary-button';
      button.textContent = `Compra • ${formatCredits(cost)}`;
      button.addEventListener('click', () => upgrade(upgrade.id));
      card.appendChild(button);
      els.upgradeList.appendChild(card);
    });
  }

  function updateHud() {
    const prod = getNetworkProduction();
    const onlineBots = state.bots.filter((bot) => !bot.paused).length;

    els.creditsStat.textContent = formatCredits(state.credits);
    els.walletStat.textContent = formatCredits(state.wallet);
    els.totalStat.textContent = formatCredits(state.totalEarned);
    els.onlineBots.textContent = String(onlineBots);
    els.unlockedCount.textContent = String(state.unlockedNetworks);
    els.prodRate.textContent = `${prod.toFixed(1)} cr/s`;
    els.statusBadge.textContent = state.routeMode ? 'ROUTING ATTIVO' : 'ROUTING SPENTO';

    els.routeStatus.classList.toggle('route-off', !state.routeMode);
    els.routeStatus.innerHTML = `<span class="dot"></span> WALLET DEMO ${state.routeMode ? 'ON' : 'OFF'}`;
  }

  function tick() {
    const now = Date.now();
    const deltaSeconds = Math.min((now - state.lastTick) / 1000, 2);
    state.lastTick = now;

    const currentNetworkReward = getNetworkProduction();
    const walletGain = currentNetworkReward * deltaSeconds * (state.routeMode ? 1 : 0.2);

    state.credits += currentNetworkReward * deltaSeconds;
    state.wallet += walletGain;
    state.totalEarned += currentNetworkReward * deltaSeconds;

    if (state.credits < 0) state.credits = 0;
    if (state.wallet < 0) state.wallet = 0;
    if (state.totalEarned < 0) state.totalEarned = 0;

    saveState();
    render();
  }

  function render() {
    renderNetworks();
    renderActiveNetwork();
    renderBots();
    renderUpgrades();
    updateHud();
  }

  function bindEvents() {
    els.scanBtn.addEventListener('click', () => {
      const active = getActiveNetwork();
      const nextIndex = state.activeNetworkId + 1;
      const next = NETWORKS[nextIndex];
      if (next && state.unlockedNetworks < MAX_NETWORKS && state.credits >= next.unlockCost) {
        state.credits -= next.unlockCost;
      }
      if (state.unlockedNetworks < MAX_NETWORKS) {
        const targetId = Math.min(nextIndex, state.unlockedNetworks);
        if (targetId < NETWORKS.length && targetId >= state.unlockedNetworks) {
          state.unlockedNetworks = Math.min(MAX_NETWORKS, state.unlockedNetworks + 1);
          state.activeNetworkId = targetId;
          showToast(`${NETWORKS[targetId].name} sbloccata.`);
          saveState();
          render();
          return;
        }
      }
      if (active.id < NETWORKS.length - 1 && state.credits >= NETWORKS[Math.min(active.id + 1, NETWORKS.length - 1)].unlockCost) {
        state.credits -= NETWORKS[Math.min(active.id + 1, NETWORKS.length - 1)].unlockCost;
      }
      showToast('Rete già attiva o credito insufficiente.');
    });

    els.hireBtn.addEventListener('click', addBot);

    els.routeBtn.addEventListener('click', () => {
      state.routeMode = !state.routeMode;
      saveState();
      render();
      showToast(state.routeMode ? 'Instradamento wallet attivo.' : 'Instradamento wallet spento.');
    });

    els.resetBtn.addEventListener('click', () => {
      state = structuredClone(DEFAULT_STATE);
      saveState();
      render();
      showToast('Salvataggio di gioco resettato.');
    });
  }

  bindEvents();
  render();
  setInterval(tick, 250);
})();

