node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 920 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.removeItem('miner-aurora-save-v1'));
  await page.reload({ waitUntil: 'networkidle' });
  const initialProd = await page.locator('#prodRate').textContent();
  if (!initialProd.includes('8.0')) throw new Error(`Unexpected production: ${initialProd}`);
  await page.waitForTimeout(1400);
  const starting = await page.locator('#creditsStat').textContent();
  if (parseFloat(starting) <= 0) throw new Error(`No passive production: ${starting}`);
  await page.locator('#routeBtn').click();
  if (!(await page.locator('#routeStatus').textContent()).includes('OFF')) throw new Error('Routing did not turn off');
  await page.waitForTimeout(1200);
  const walletOff = await page.locator('#walletStat').textContent();
  await page.locator('#routeBtn').click();
  await page.locator('#hireBtn').click();
  if (await page.locator('.bot-card').count() !== 3) throw new Error('Bot hiring failed');
  await page.locator('.bot-card button').first().click();
  if (!(await page.locator('.bot-card').first().locator('.bot-status').first().textContent()).includes('In pausa')) throw new Error('Bot pause failed');
  await page.evaluate(() => {
    const key = 'miner-aurora-save-v1'; const s = JSON.parse(localStorage.getItem(key)); s.credits = 100000; localStorage.setItem(key, JSON.stringify(s));
  });
  await page.reload({ waitUntil: 'networkidle' });
  await page.locator('#upgradeList .upgrade-card button').first().click();
