.app-view[hidden] { display: none !important; }

.view-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.025);
}

.nav-button {
  border: 0;
  border-radius: 10px;
  padding: 9px 13px;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  transition: color 0.18s ease, background 0.18s ease;
}

.nav-button:hover, .nav-button.active {
  color: var(--text);
  background: rgba(126, 246, 197, 0.1);
}

.live-view, .settings-view {
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-width: 0;
}

.live-intro h1, .settings-heading h1 {
  margin: 8px 0;
  font-size: clamp(1.7rem, 3vw, 2.4rem);
}

.live-intro p, .settings-heading p {
  max-width: 760px;
  color: var(--muted);
  line-height: 1.6;
}

.accent-dot { color: var(--accent); }
.live-columns, .settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  min-width: 0;
}

.search-form {
  display: flex;
  gap: 9px;
  margin-top: 16px;
}

.search-form input, .settings-card input, .settings-card select {
  width: 100%;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  color: var(--text);
  background: rgba(3, 9, 17, 0.72);
  font: inherit;
}

.settings-card select option { color: var(--text); background: var(--bg-alt); }
.search-form button { flex: 0 0 auto; }
.hint, .notice { color: var(--muted); font-size: 0.86rem; line-height: 1.55; }
.notice {
  padding: 12px 14px;
  border: 1px solid rgba(247, 200, 109, 0.22);
  border-radius: 12px;
  background: rgba(247, 200, 109, 0.045);
}
.result-box, .market-result, .estimate-card {
  min-width: 0;
  padding: 13px;
  overflow-wrap: anywhere;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--text);
  line-height: 1.55;
}
.result-box.is-error { border-color: rgba(255, 125, 141, 0.45); color: #ffb1ba; }
.result-list { display: grid; gap: 9px; }
.market-result { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 12px; }
.market-change { font-size: 0.85rem; }
.market-change.positive { color: var(--accent); }
.market-change.negative { color: var(--danger); }
.live-badge {
  padding: 6px 9px;
  border: 1px solid rgba(126, 246, 197, 0.28);
  border-radius: 999px;
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}
.estimate-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.estimate-card { display: flex; flex-direction: column; gap: 10px; }
.estimate-card span { color: var(--muted); font-size: 0.78rem; }
.estimate-card strong { font-size: clamp(1rem, 2vw, 1.3rem); overflow-wrap: anywhere; }
.settings-card { display: flex; flex-direction: column; align-items: stretch; gap: 9px; }
.settings-card h2 { margin: 0 0 4px; }
.settings-card label { margin-top: 5px; color: var(--muted); font-size: 0.88rem; }
.settings-card .hint { margin: 2px 0 7px; }
.setting-toggle { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-top: 13px; border-top: 1px solid var(--line); }
.setting-toggle span { color: var(--muted); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 900px) {
  .estimate-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 700px) {
  .live-columns, .settings-grid { grid-template-columns: 1fr; }
  .topbar { flex-wrap: wrap; }
  .view-nav { order: 3; width: 100%; justify-content: stretch; }
  .nav-button { flex: 1; padding-inline: 8px; }
}

@media (max-width: 480px) {
  .search-form { flex-direction: column; }
  .search-form button { width: 100%; }
  .market-result { grid-template-columns: 1fr auto; }
  .market-result strong { grid-column: 1 / -1; }
  .estimate-grid { grid-template-columns: 1fr; }
}

