async function refreshLiveData() {
  const [priceResult, hashrateResult, heightResult] = await Promise.allSettled([
    fetchJson(`https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=${settings.currency}`),
    fetchJson('https://mempool.space/api/v1/mining/hashrate/1m'),
    fetch('https://mempool.space/api/blocks/tip/height').then(async (response) => {
      if (!response.ok) throw new Error('Altezza blocco non disponibile.');
      const value = Number(await response.text());
      if (!Number.isFinite(value)) throw new Error('Altezza blocco non valida.');
      return value;
    }),
  ]);
  if (priceResult.status === 'fulfilled') marketData.price = Number(priceResult.value?.bitcoin?.[settings.currency]) || null;
  if (hashrateResult.status === 'fulfilled') {
    const records = hashrateResult.value?.hashrates || [];
    const latest = records.at(-1);
    if (Number.isFinite(Number(latest?.avgHashrate))) marketData.networkHashrate = Number(latest.avgHashrate);
  }
  if (heightResult.status === 'fulfilled') marketData.height = heightResult.value;
  marketData.updatedAt = Date.now();

