  console.log('LIVE API', live);

  await evaluate(`document.querySelector('[data-view="settingsView"]').click();
    window.fetch=async (input)=>{const u=String(input); if(u.includes('coingecko')) return new Response(JSON.stringify({bitcoin:{eur:-1}}),{status:200}); if(u.includes('/mining/hashrate/')) return new Response(JSON.stringify({hashrates:[]}),{status:200}); if(u.includes('/blocks/tip/height')) return new Response('not-a-height',{status:200}); return new Response('{}',{status:404});};
    document.querySelector('[data-view="liveView"]').click(); 'mocked'`);
  await new Promise((resolve) => setTimeout(resolve, 150));
  console.log('MALFORMED API', await evaluate(`({updated:liveUpdated.textContent,gross:grossEstimate.textContent,btc:btcEstimate.textContent,estimate:estimateStatus.textContent})`));

  await evaluate(`document.querySelector('[data-view="settingsView"]').click(); currencySetting.value='eur'; saveSettingsBtn.click();
    window.__eurResolve=null; window.__eurStarted=false;
    window.fetch=(input)=>{const u=String(input);
      if(u.includes('coingecko')&&u.includes('vs_currencies=eur')) {window.__eurStarted=true;return new Promise(resolve=>window.__eurResolve=resolve);}
      if(u.includes('coingecko')) return Promise.resolve(new Response(JSON.stringify({bitcoin:{usd:200}}),{status:200}));
      if(u.includes('/mining/hashrate/')) return Promise.resolve(new Response(JSON.stringify({hashrates:[{avgHashrate:1e20}]}),{status:200}));
      if(u.includes('/blocks/tip/height')) return Promise.resolve(new Response('900000',{status:200}));
      return Promise.resolve(new Response('{}',{status:404}));};
    document.querySelector('[data-view="liveView"]').click(); 'eur-started'`);
  await new Promise((resolve) => setTimeout(resolve, 100));
  console.log('RACE STARTED', await evaluate(`window.__eurStarted`));
  await evaluate(`document.querySelector('[data-view="settingsView"]').click(); currencySetting.value='usd'; saveSettingsBtn.click(); document.querySelector('[data-view="liveView"]').click(); 'usd-started'`);
  await new Promise((resolve) => setTimeout(resolve, 100));
  const usd = await evaluate(`liveUpdated.textContent`);
  await evaluate(`window.__eurResolve(new Response(JSON.stringify({bitcoin:{eur:1}}),{status:200})); 'eur-resolved'`);
  await new Promise((resolve) => setTimeout(resolve, 150));
  const after = await evaluate(`({updated:liveUpdated.textContent,gross:grossEstimate.textContent,estimate:estimateStatus.textContent})`);
  console.log('CURRENCY RACE', { afterUsdRefresh: usd, afterOldEurResolved: after });
  console.log('BROWSER ERRORS', errors);
  ws.close();
  if (!live.gross || live.gross === '—' || !live.net) throw new Error('Stima live non calcolata');
